  cutoff: IsoTimestamp,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(
      and(
        isNotNull(organizations.archivedAt),
        lte(organizations.archivedAt, cutoff),
      ),
    )
    .all();

  return rows.map((row) => brandId<OrgId>(row.id));
